import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Carousel } from "react-responsive-carousel";
function Sketches() {
  const navigate = useNavigate();
  const images2 = ["/bodyfacec1.avif","/bodyfacec1.avif","/bodyfacec1.avif","/bodyfacec1.avif","/bodyfacec1.avif","/bodyfacec1.avif","/bodyfacec1.avif",];
  const images = [
    "sketch1.avif",
    "sketch2.avif",
    "sketch3.avif",
    "sketch4.avif",
    "sketch5.avif",
    "sketch6.avif",
    "sketch7.avif",
    "sketch8.avif",
  ];

  return (
    <>
      {/* Go Back Button */}
      <p
        className="underline text-base sm:text-lg md:text-xl lg:text-2xl cursor-pointer pl-5 mt-5"
        onClick={() => navigate(-1)}
      >
        Go Back
      </p>

      {/* Heading Section */}
      <div className="flex flex-col items-center justify-center mt-10">
        <h2 className="text-5xl font-bold text-red-500 text-center mt-2 mb-10">
          SKETCHES AND PAINTINGS
        </h2>
      </div>

      {/* Image Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-40 px-4 md:px-10 lg:px-20">
        {images.map((image, index) => (
          <img
            key={index}
            src={image}
            alt={`Sketch ${index + 1}`}
            className="w-full h-auto shadow-lg"
          />
        ))}
      </div>

     {/* Carousel 2 */}
             <div className="w-full md:w-1/2">
               <Carousel
                 autoPlay
                 infiniteLoop
                 showThumbs={false}
                 showStatus={false}
                 interval={3000}
                 showArrows
               >
                 {images2.map((image, index) => (
                   <div key={index} className="flex justify-center">
                     <img src={image} alt={`Design Slide ${index + 1}`} className="rounded-lg w-full h-[300px] sm:h-[400px] md:h-[500px] object-cover" />
                   </div>
                 ))}
               </Carousel>
             </div>

    </>
  );
}

export default Sketches;
